from src.nodes.base import BaseNode
from src.runtime.assets.realization import get_scene_asset_realizer
import json

class Hou_Mcp_Asset_Realize(BaseNode):
    name = "hou_mcp_asset_realize"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("assets_json",      "string", widget_type="text")
        self.add_input("zone_map_json",    "string", widget_type="text", default="{}")
        self.add_input("layout_plan_json", "string", widget_type="text", default="")
        self.add_output("realization_plan_json", "string")
        self.add_output("transaction_ops_json",  "string")
        self.add_output("asset_count",           "int")
        self.add_output("complexity",            "string")
        self.add_output("realize_ok",            "bool")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        assets_json      = inputs.get("assets_json", "") or ""
        zone_map_json    = inputs.get("zone_map_json", "{}") or "{}"
        layout_plan_json = inputs.get("layout_plan_json", "") or ""

        if not assets_json.strip():
            self.log_error("No assets_json provided.")
            return {"realization_plan_json": "{}", "transaction_ops_json": "[]", "asset_count": 0, "complexity": "simple", "realize_ok": False, "exec_out": True}

        try:
            assets = json.loads(assets_json)
            if isinstance(assets, dict):
                assets = [assets]
        except Exception as exc:
            self.log_error(f"Failed to parse assets_json: {exc}")
            return {"realization_plan_json": "{}", "transaction_ops_json": "[]", "asset_count": 0, "complexity": "simple", "realize_ok": False, "exec_out": True}

        layout_plan = None
        if layout_plan_json.strip():
            try:
                layout_plan = json.loads(layout_plan_json)
            except Exception:
                pass

        try:
            plan = get_scene_asset_realizer().build_realization_plan(assets, layout_plan)
            ops = get_scene_asset_realizer().generate_transaction_operations(plan)
            ok = not bool(plan.errors)
            self.log_info(f"Realization plan: {plan.asset_count} assets, {len(ops)} ops, complexity={plan.estimated_complexity}")
            return {
                "realization_plan_json": json.dumps(plan.to_dict(), sort_keys=True, default=str),
                "transaction_ops_json":  json.dumps(ops, sort_keys=True, default=str),
                "asset_count":           plan.asset_count,
                "complexity":            plan.estimated_complexity,
                "realize_ok":            ok,
                "exec_out": True,
            }
        except Exception as exc:
            self.log_error(f"Asset realization failed: {exc}")
            return {"realization_plan_json": "{}", "transaction_ops_json": "[]", "asset_count": 0, "complexity": "simple", "realize_ok": False, "exec_out": True}

def register_node():
    return Hou_Mcp_Asset_Realize
